func BdClass(cp int32) int32 {
	// The bidi class code of a code point: the last run that starts at or before it. -1 (no value) is ON.
	if (cp < 0) || (cp > 1114111) {
		return 0
	}
	var lo int32 = 0
	var hi int32 = 1233 - 1
	var mid int32 = 0
	for lo < hi {
		mid = (lo + hi + 1) / 2
		if bidiclass.BcRuns[mid*2+0] <= cp {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return bidiclass.BcRuns[lo*2+1]
}

func BdStrong(cp int32) int32 {
	// 1 when the code point is a strong right-to-left LETTER (Hebrew, Arabic, ...), 2 a strong left-to-right
	// one, 0 otherwise: a digit, a separator and a mark are not strong. What decides a word's direction.
	var k int32 = BdClass(cp)
	if (k == 1) || (k == 8) {
		return 1
	}
	if k == 2 {
		return 2
	}
	return 0
}

func bdBracket(cp int32) int32 {
	// The row of the paired-bracket table (bidiclass.kin) of a code point, or -1.
	var lo int32 = 0
	var hi int32 = 130 - 1
	var mid int32 = 0
	if hi < 0 {
		return -1
	}
	for lo < hi {
		mid = (lo + hi) / 2
		if bidiclass.BcBrackets[mid*3+0] < cp {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if bidiclass.BcBrackets[lo*3+0] == cp {
		return lo
	}
	return -1
}

func BdMirror(cp int32) int32 {
	// L4: the code point whose glyph is the mirror image of this one's (a parenthesis, a bracket, an angle,
	// a comparison sign: BidiMirroring.txt), or the code point itself. A glyph drawn at an odd level (inside
	// right-to-left text) is the mirror image of the character's own, so text read back from glyphs, in logical
	// order, has the mirror of what the glyph shows at every level-1 position.
	var lo int32 = 0
	var hi int32 = 438 - 1
	var mid int32 = 0
	if hi < 0 {
		return cp
	}
	for lo < hi {
		mid = (lo + hi) / 2
		if bidiclass.BcMirrors[mid*2+0] < cp {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if bidiclass.BcMirrors[lo*2+0] == cp {
		return bidiclass.BcMirrors[lo*2+1]
	}
	return cp
}

